from pathlib import Path
import xml.etree.ElementTree as ET
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak

ROOT=Path(__file__).resolve().parents[1];JUNIT=ROOT/'test-results'/'junit.xml';OUT=ROOT/'output'/'pdf'/'SBB-Oxygen-House-Admin-Contact-Messages-Test-Report.pdf'
if not JUNIT.exists():raise SystemExit('Run npm run test:contact-messages:all first.')
rows=[]
for suite in ET.parse(JUNIT).getroot().findall('testsuite'):
 for case in suite.findall('testcase'):
  name=case.get('name','')
  if 'CONTACT-MATRIX-' not in name:continue
  failure=case.find('failure');result='FAILED'if failure is not None else('SKIPPED'if case.find('skipped')is not None else'PASSED')
  finding='Search leaves unrelated rows visible.'if failure is not None and 'CONTACT-MATRIX-F-001'in name else'Verified'
  rows.append([name.split('>')[-1].strip(),suite.get('hostname','Unknown'),result,f"{float(case.get('time',0)):.1f}s",finding])
if not rows:raise SystemExit('No Contact Messages matrix results found.')
p=sum(r[2]=='PASSED'for r in rows);f=sum(r[2]=='FAILED'for r in rows);sk=sum(r[2]=='SKIPPED'for r in rows)
OUT.parent.mkdir(parents=True,exist_ok=True);styles=getSampleStyleSheet();navy=colors.HexColor('#102331');teal=colors.HexColor('#0B6980');line=colors.HexColor('#B9C9D1');green=colors.HexColor('#DDF4E6');red=colors.HexColor('#FADADA');amber=colors.HexColor('#FFF0C2')
title=ParagraphStyle('Title',parent=styles['Title'],fontSize=19,leading=23,textColor=navy,spaceAfter=3*mm);h=ParagraphStyle('H',parent=styles['Heading1'],fontSize=13,leading=16,textColor=teal,spaceBefore=3*mm,spaceAfter=2*mm);body=ParagraphStyle('Body',parent=styles['BodyText'],fontSize=8.5,leading=12,textColor=navy);small=ParagraphStyle('Small',parent=body,fontSize=7,leading=9);tiny=ParagraphStyle('Tiny',parent=body,fontSize=5.7,leading=6.6)
def footer(canvas,doc):
 canvas.saveState();canvas.setStrokeColor(line);canvas.line(14*mm,12*mm,196*mm,12*mm);canvas.setFillColor(colors.HexColor('#607783'));canvas.setFont('Helvetica',6.5);canvas.drawString(14*mm,8*mm,'SBB Oxygen House - Admin Contact Messages Test Report');canvas.drawRightString(196*mm,8*mm,f'Page {doc.page}');canvas.restoreState()
doc=SimpleDocTemplate(str(OUT),pagesize=A4,leftMargin=14*mm,rightMargin=14*mm,topMargin=14*mm,bottomMargin=17*mm,title='Admin Contact Messages Test Report',author='Calibur Automation')
story=[Paragraph('SBB OXYGEN HOUSE',ParagraphStyle('Brand',parent=small,textColor=teal,fontSize=10,leading=12)),Paragraph('ADMIN CONTACT MESSAGES TEST REPORT',title),Paragraph('Functional, UI, nonfunctional and web/mobile browser compatibility evidence',body),Spacer(1,5*mm)]
summary=Table([['Target','Matrix','Passed','Failed','Skipped'],['/admin/contact',len(rows),p,f,sk]],colWidths=[72*mm,27*mm,27*mm,27*mm,27*mm]);summary.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),teal),('TEXTCOLOR',(0,0),(-1,0),colors.white),('ALIGN',(1,0),(-1,-1),'CENTER'),('GRID',(0,0),(-1,-1),.4,line),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),8),('PADDING',(0,0),(-1,-1),6)]));story +=[summary,Spacer(1,5*mm),Paragraph('Executive result',h),Paragraph(f'The eight-profile compatibility matrix completed with <b>{p} passed, {f} failed and {sk} skipped</b>. Layout fit and critical accessibility, HTTPS and runtime checks passed in every profile. Search failed consistently because entering an exact existing subject did not remove unrelated rows.',body),Paragraph('Confirmed finding',h)]
findings=[['Severity','Area','Finding and expected correction'],['High','Message search','Typing an existing subject leaves 15 unrelated messages visible across all eight profiles. Connect the search input to the inbox dataset and filter by sender, email, subject and message text.']]
ft=Table([[Paragraph(str(c),small)for c in row]for row in findings],colWidths=[25*mm,42*mm,113*mm]);ft.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),navy),('TEXTCOLOR',(0,0),(-1,0),colors.white),('BACKGROUND',(0,1),(0,-1),amber),('GRID',(0,0),(-1,-1),.4,line),('VALIGN',(0,0),(-1,-1),'TOP'),('PADDING',(0,0),(-1,-1),5)]));story +=[ft,Spacer(1,4*mm),Paragraph('Test-data and mutation policy',h),Paragraph('This admin section is an inbox and provides no create or edit form. Therefore there are no field-entry validations to test on this page. Existing Playwright QA messages are used as read-only test data for sender, email, subject and body assertions. The View action is opened and closed. The Delete Message warning is opened and cancelled only; no production enquiry is deleted.',body),Paragraph('Browser scope',h),Paragraph('Chrome and Edge use installed vendor browsers. Firefox uses Playwright Firefox. Safari-compatible profiles use Playwright WebKit on Windows and represent engine-level compatibility, not certification on physical Apple Safari.',body)]
story +=[PageBreak(),Paragraph('Detailed coverage',title)]
coverage=[('Identity and route','Authenticated HTTPS route, Contact Messages heading, descriptive text and expected columns.'),('Inbox data','At least one live message; sender/name, email, subject and received date structure.'),('Search validation','Existing exact subject and a guaranteed no-match value; unrelated rows must be removed.'),('View message','Eye action opens the selected subject with sender details and non-empty message content; Escape closes it.'),('Delete safety','Trash action opens Delete Message confirmation; Cancel preserves the complete row count.'),('UI','Search size, row-action target sizes, keyboard focus and page-width overflow.'),('Accessibility','Axe critical WCAG checks on listing plus separate view and delete dialog scans.'),('Responsive','Document width checked against viewport width on desktop and mobile profiles.'),('Performance','Authenticated inbox readiness threshold of 10 seconds.'),('Security','HTTPS, exact authenticated route and protection from login redirection.'),('Runtime quality','Uncaught browser errors and HTTP 5xx responses are monitored.'),('Compatibility','Chrome, Edge, Firefox and Safari-compatible web/mobile: 8 profiles x 3 matrix checks = 24 results.')]
ct=Table([['Testing area','What was verified']]+[[Paragraph(a,small),Paragraph(b,small)]for a,b in coverage],colWidths=[43*mm,137*mm],repeatRows=1);ct.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),teal),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.35,line),('VALIGN',(0,0),(-1,-1),'TOP'),('PADDING',(0,0),(-1,-1),4)]));story +=[ct,Spacer(1,4*mm),Paragraph('Conclusion',h),Paragraph('Message listing, responsive layout, HTTPS, critical accessibility and runtime quality are operational. Search is a cross-browser application defect. View and delete-cancel automation is implemented independently in the full Chrome suite; the matrix functional flow stops at the failed search assertion, correctly preserving that failure evidence.',body)]
story +=[PageBreak(),Paragraph('Compatibility matrix results',title),Paragraph('Rows below come from the latest JUnit execution produced by npm run test:contact-messages:all.',body),Spacer(1,3*mm)]
data=[['Test case','Profile','Result','Time','Finding']]+[[Paragraph(r[0],tiny),Paragraph(r[1],tiny),Paragraph(r[2],tiny),Paragraph(r[3],tiny),Paragraph(r[4],tiny)]for r in rows];dt=Table(data,colWidths=[77*mm,34*mm,20*mm,15*mm,34*mm],repeatRows=1);cmd=[('BACKGROUND',(0,0),(-1,0),teal),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.3,line),('VALIGN',(0,0),(-1,-1),'TOP'),('PADDING',(0,0),(-1,-1),3)]
for i,r in enumerate(rows,1):cmd.append(('BACKGROUND',(2,i),(2,i),green if r[2]=='PASSED'else red if r[2]=='FAILED'else amber))
dt.setStyle(TableStyle(cmd));story.append(dt);doc.build(story,onFirstPage=footer,onLaterPages=footer);print(OUT)
